import{_ as l,o as i,c as o,a0 as a}from"./chunks/framework.DqMqoJl9.js";const v=JSON.parse('{"title":"搭建本地开发环境","description":"","frontmatter":{},"headers":[],"relativePath":"webpack/7-dev-server.md","filePath":"webpack/7-dev-server.md","lastUpdated":1791573371000}'),t={name:"webpack/7-dev-server.md"};function c(d,e,r,p,s,n){return i(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="搭建本地开发环境" tabindex="-1">搭建本地开发环境 <a class="header-anchor" href="#搭建本地开发环境" aria-label="Permalink to &quot;搭建本地开发环境&quot;">​</a></h1><p>使用 <code>webpack-dev-server</code> 创建本地服务</p><p>功能：</p><ul><li>live reloading 代码发生改变时自动编译并且刷新浏览器</li><li>不会生成打包文件，文件存在内存中</li><li>路径重定向</li><li>支持 https</li><li>浏览器中显示编译错误</li><li>接口代理</li><li>模块热更新-不刷新浏览器更新代码</li></ul><p>配置：</p><ul><li><code>contentBase</code> 提供内容的路径，即项目打包后的根目录</li><li><code>port</code> 端口</li><li><code>historyApiFallback</code> 使用 html5 history 时需要配置这个参数，不配置会显示 404</li><li><code>https</code> 本地会自动生成证书，或者自己指定</li><li><code>proxy</code> 代理</li><li><code>hot</code> 模块热更新</li><li><code>openpage</code> 初始页面</li><li><code>lazy</code> 访问到的内容才会编译（多页面应用比较有用）</li><li><code>overlay</code> 遮罩，显示错误信息</li></ul>',6)])])}const h=l(t,[["render",c]]);export{v as __pageData,h as default};
